  // Shown when someone picked "I'm a Trainer" and successfully logged in or
  // created an account, but their email isn't on any gym's trainer roster —
  // instead of silently treating them as a client with no explanation.
  // Sept 15 2026, Jimmy: "fix also those 3" — last two of the gate-style
  // screens still on the plain static layout (Owner access, reset
  // password, and payment-overdue already got this same GateDecor +
  // staggered popIn/fadeUp treatment). Same content/logic on both, just no
  // longer flat.
  // Sept 18 2026, Jimmy: two review findings landed on this exact screen —
  // #16 ("a routine 'still processing' screen titled 'Something went
  // wrong'" — reads as a hard error for what's often just a transient
  // signup-sync hiccup) and #12 (rejecting a pending trainer used to leave
  // them permanently stranded here: handleRejectTrainer only ever deletes
  // the `trainers` roster row, never the real Supabase Auth login it came
  // from — so re-clicking "Create your account" always failed with
  // Supabase's own "already registered" error, and logging in instead just
  // landed back on this same screen with no roster row to match, forever).
  //
  // Fixed both by turning this from a dead-end/reload-and-pray screen into
  // a real recovery path: a small inline form re-submits a fresh trainer
  // application (same shape as a first-time signup — name, last name,
  // phone, is_approved: false) directly from here, using the live session
  // that already exists rather than requiring a doomed re-signup. Covers
  // BOTH cases — a rejected trainer re-applying for real, and someone who
  // hit a genuine transient failure and just needs their row created.
  // Title/copy softened to match: this is a routine "let's finish your
  // application" step, not an error state.
  function TrainerNotOnRosterScreen({ email, onLogout, onReapplied }) {
    const [name, setName] = useState("");
    const [lastName, setLastName] = useState("");
    const [phone, setPhone] = useState("");
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState("");
    const [submitted, setSubmitted] = useState(false);
    // Sept 18 2026 retest round 2: `submitting` (state) is what drives the
    // button's disabled look, but a re-entrancy check that reads `submitting`
    // itself doesn't actually protect against two taps landing before React
    // commits a re-render — both taps run off the same closure, where
    // `submitting` is still false for both. A ref updates synchronously,
    // independent of render/commit timing, so it's checked here instead —
    // same pattern this file already uses for real synchronous guards
    // (e.g. draggingRef).
    const submittingRef = useRef(false);

    // Best-effort prefill from whatever name they typed at signup — still
    // editable, and not fatal if it's missing (a first-time-here trainer
    // whose original metadata never got picked up, say).
    useEffect(() => {
      if (!sb) return;
      sb.auth.getUser().then(({ data }) => {
        const meta = data && data.user && data.user.user_metadata;
        if (meta) {
          if (meta.display_name && !name) setName(meta.display_name);
          if (meta.last_name && !lastName) setLastName(meta.last_name);
        }
      });
    }, []);

    async function handleReapply() {
      // Sept 18 2026 retest round 2: checking submittingRef (a ref, updated
      // synchronously right here — not state, which only updates on the
      // next render) actually closes the double-tap gap — two taps in the
      // same instant now genuinely can't both get past this line, unlike
      // the previous state-based check which read the same stale closure
      // value for both.
      if (submittingRef.current) return;
      setError("");
      if (!name.trim()) { setError("Enter your first name."); return; }
      if (!phone.trim()) { setError("Enter your phone number — it's how JimFit matches your first payment to you."); return; }
      if (!sb || !email) { setError("Couldn't reach the server — try again."); return; }
      submittingRef.current = true;
      setSubmitting(true);
      const dupeId = await findTrainerIdWithPhone(sb, phone.trim(), null);
      if (dupeId) {
        submittingRef.current = false;
        setSubmitting(false);
        setError("This phone number is already registered to another trainer account. Contact your manager if you think this is a mistake.");
        return;
      }
      const { data, error: err } = await sb.from("trainers").insert([{
        name: name.trim(), last_name: lastName.trim() || null, email, phone: phone.trim(), invite_code: randomInviteCode(), is_approved: false
      }]).select();
      submittingRef.current = false;
      setSubmitting(false);
      if (err || !data || !data[0]) {
        setError(`Couldn't send that${err && err.message ? ` (${err.message})` : ""}. Try again.`);
        return;
      }
      setSubmitted(true);
      // Drop straight into the normal pending-approval screen instead of
      // requiring a logout/reload to pick up the row that was just created.
      if (onReapplied) onReapplied(data[0]);
    }

    if (submitted) return null; // onReapplied already swapped the screen; avoid a flash of this one

    return e("div", { style: { ...styles.gateWrap, position: "relative" } },
      e(GateDecor, {}),
      e("div", { style: { ...styles.gateCard, position: "relative", zIndex: 1 } },
        e("div", { style: { opacity: 0, animation: "popIn 0.4s cubic-bezier(.16,1,.3,1) 0.06s forwards" } }, e(BrandMark, {})),
        e("h1", { style: { ...styles.gateTitle, opacity: 0, animation: "fadeUp 0.4s cubic-bezier(.16,1,.3,1) 0.16s forwards" } }, "Let's finish your application"),
        e("p", { style: { ...styles.gateSub, opacity: 0, animation: "fadeUp 0.4s cubic-bezier(.16,1,.3,1) 0.26s forwards" } },
          `${email || "This email"} isn't listed as a trainer yet — this can happen right after signing up, or if your application needs to be resent. Confirm a couple of details below and we'll send it through for approval.`
        ),
        e("div", { style: { width: "100%", opacity: 0, animation: "fadeUp 0.4s cubic-bezier(.16,1,.3,1) 0.34s forwards", display: "flex", flexDirection: "column", gap: 10, marginTop: 8 } },
          e("input", { style: styles.input, placeholder: "First name", value: name, onChange: (ev) => setName(ev.target.value) }),
          e("input", { style: styles.input, placeholder: "Last name (optional)", value: lastName, onChange: (ev) => setLastName(ev.target.value) }),
          e("input", { style: styles.input, type: "tel", placeholder: "Phone number", value: phone, onChange: (ev) => setPhone(ev.target.value) })
        ),
        error && e("span", { style: styles.inlineError }, error),
        e("button", {
          style: { ...styles.saveBtn, marginTop: 14, opacity: 0, animation: "fadeUp 0.4s cubic-bezier(.16,1,.3,1) 0.46s forwards", ...(submitting ? styles.btnDisabled : {}) },
          disabled: submitting, onClick: handleReapply
        }, submitting ? "Sending…" : "Send my trainer application"),
        e("button", { style: { ...styles.demoLinkBtn, marginTop: 10, opacity: 0, animation: "fadeUp 0.4s cubic-bezier(.16,1,.3,1) 0.54s forwards" }, onClick: onLogout }, "Log out")
      )
    );
  }

