  // Client-facing browse screen — shown to every non-manager client now
  // (previously self-train only, see isSelfTrainClient in the client shell).
  // A client who already has a real trainer sees the same screen framed as
  // "change trainer" instead of "find a trainer" (currentTrainerName), and
  // their current trainer is filtered out of the list — no point requesting
  // the person they're already with. Either way the request lands in the
  // same trainer_requests queue/approval flow (TrainerRequestsPanel), so a
  // switch works exactly like a first-time match: nothing changes until the
  // manager approves it. Reads via a SECURITY DEFINER RPC
  // (browsable_trainer_profiles) rather than a direct table select, so
  // browsing only ever exposes the safe coaching-profile columns (name/bio/
  // specialties/certifications/years) and never a trainer's email or other
  // row data — same "don't rely on hiding logic in the frontend" principle
  // as everything else in the security checklist.
  function FindTrainerPanel({ clientId, clientName = null, currentTrainerId = null, currentTrainerName = null }) {
    const [trainers, setTrainers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [myRequest, setMyRequest] = useState(null);
    // Sept 18 2026 retest round 2: `loading` only tracked the trainer-list
    // fetch below — the "do I already have a pending request" fetch (the
    // next useEffect) ran independently with nothing gating the panel on
    // it. If that one resolved slower (or the trainer list resolved
    // faster), the panel could render with `pending` still false for a
    // moment even though a real pending request existed, leaving a window
    // for a duplicate request on a fast tap or slow connection. Both
    // fetches now have to land before "Loading trainers…" clears.
    const [myRequestLoaded, setMyRequestLoaded] = useState(false);
    const [requesting, setRequesting] = useState(null);
    const [requestingSelf, setRequestingSelf] = useState(false);
    const [cancelling, setCancelling] = useState(false);
    const [error, setError] = useState("");
    // Sept 13 2026, Jimmy: "can we make the trainer section more pro when
    // the clients want to choose and less cluttery?" — trainer cards used
    // to dump every specialty chip, every certification chip, and the full
    // bio quote on screen at once, in three different colors, which read
    // as busy rather than professional. Cards now open collapsed (name,
    // photo, years, and just the top few specialties to scan), with
    // certifications and the bio tucked behind a tap-to-expand — same data,
    // shown on demand instead of all at once.
    const [expandedIds, setExpandedIds] = useState({});
    function toggleExpanded(id) {
      setExpandedIds((prev) => ({ ...prev, [id]: !prev[id] }));
    }

    useEffect(() => {
      if (!sb) { setLoading(false); return; }
      sb.rpc("browsable_trainer_profiles").then(({ data, error: err }) => {
        if (!err && data) setTrainers(data);
        setLoading(false);
      });
    }, []);

    useEffect(() => {
      if (!sb || !clientId) { setMyRequestLoaded(true); return; }
      sb.from("trainer_requests").select("*").eq("client_id", clientId).order("created_at", { ascending: false }).limit(1).maybeSingle().then(({ data, error: err }) => {
        if (!err && data) setMyRequest(data);
        setMyRequestLoaded(true);
      });
    }, [clientId]);

    async function handleRequest(trainerId) {
      if (!sb || !clientId) return;
      setRequesting(trainerId);
      setError("");
      const { data, error: err } = await sb.from("trainer_requests").insert([{ client_id: clientId, trainer_id: trainerId }]).select();
      setRequesting(null);
      if (!err && data && data[0]) {
        setMyRequest(data[0]);
        // Sept 18 2026, Jimmy: "if a client requested a trainer to me see the
        // request and the trainer also" — both the requested trainer and the
        // gym owner get notified right when the request comes in, instead of
        // only showing up next time either of them happens to check the
        // Requests list.
        const who = clientName ? `${clientName} requested` : "A client requested";
        notifyTrainer(trainerId, `${who} you as their trainer.`);
        notifyOwner(`${who} a trainer.`, { viaTrainerId: trainerId });
      } else {
        setError("Couldn't send the request — try again.");
      }
    }

    // "Stop training with anyone" isn't a pick off the browse list — it
    // routes to the same reserved Self-Training bucket row every no-code
    // signup lands in, found/created the same way (ensureSelfTrainRow is a
    // plain read of the trainers table by its reserved email, already used
    // client-side at signup — no new access needed). Once found, it's just
    // handleRequest with that row's id, so it goes through the exact same
    // pending-request → manager-approval path as any other switch.
    async function handleRequestSelfTrain() {
      if (!sb || !clientId) return;
      setError("");
      setRequestingSelf(true);
      const selfRow = await ensureSelfTrainRow();
      if (!selfRow) { setRequestingSelf(false); setError("Couldn't reach the self-training option — try again."); return; }
      await handleRequest(selfRow.id);
      setRequestingSelf(false);
    }

    // Sept 13 2026, Jimmy: "i want also he can cancel the request the
    // client" — a client with a pending request can back out of it
    // themselves instead of waiting on the manager to decline it. Reuses
    // the same "declined" status the manager's own Decline button already
    // writes (TrainerRequestsPanel.handleDecline above), so it's a status
    // this table already accepts — clearing myRequest afterwards re-opens
    // the trainer list / self-train button for a fresh request.
    async function handleCancelRequest() {
      if (!sb || !myRequest) return;
      setCancelling(true);
      setError("");
      const { error: err } = await sb.from("trainer_requests").update({ status: "declined" }).eq("id", myRequest.id);
      setCancelling(false);
      if (!err) {
        setMyRequest(null);
      } else {
        setError("Couldn't cancel the request — try again.");
      }
    }

    if (loading || !myRequestLoaded) return e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, "Loading trainers…"));

    const pending = myRequest && myRequest.status === "pending";
    // Sept 19 2026 inspection fix: single shared lock covering both the
    // self-train button and every trainer card's own button, so a rapid
    // tap on a second button can't fire a second request while the first
    // one's insert is still in flight — `requesting`/`requestingSelf`
    // individually only protected the specific button just tapped.
    const anyRequestInFlight = requesting != null || requestingSelf;
    const switching = !!currentTrainerName;
    // No point offering to "switch" to the trainer they're already with.
    const visibleTrainers = currentTrainerId ? trainers.filter((t) => t.id !== currentTrainerId) : trainers;

    return e("div", { style: { padding: "0 2px" } },
      // Visual-only restyle (Sept 2026, Jimmy: "the training with coach tab,
      // visuals only") — same left-accent sectionHead wrapper, just the
      // title font swapped from the old Oswald sectionTitle to the Space
      // Grotesk progressCardTitle already used on the Diet/Progress tabs'
      // card headers, so this screen reads as part of the same restyled set
      // instead of the older look. No copy, data, or behavior changed.
      e("div", { style: styles.sectionHead }, e("span", { style: styles.progressCardTitle }, switching ? "Change trainer" : "Find a trainer")),
      e("p", { style: { ...styles.profileGoalText, fontSize: 12, marginBottom: 14 } },
        switching
          ? `You're currently training with ${currentTrainerName}. Browse other trainers below and request a switch — it goes to our team to review, so nothing changes until it's approved.`
          : "Browse real trainers and request one — your request goes to our team to match you up, so you'll hear back rather than being left waiting on a stranger."
      ),
      // Sept 13 2026, Jimmy: "to see your request is pending phrase and
      // well match you with a trainer soon to be in yellow" — the pending
      // notice now uses the warning/amber token instead of the neutral
      // gray setupNotice default, plus a Cancel request button so the
      // client isn't stuck waiting on the manager to back out.
      // Sept 18 2026, Jimmy: "trainer-request status has no visual progress
      // indicator, unlike the payment flow" review finding — same 3-dot
      // stepper PaymentStatusStepper already uses for "Sent → Under review →
      // Approved", reused here so "pending" reads as visible progress
      // instead of an unclear stuck-looking state. Copy/cancel behavior
      // below is unchanged, just the dots row and a short stage line added.
      pending && e("div", { style: { ...styles.setupNotice, marginBottom: 14, flexDirection: "column", alignItems: "stretch", gap: 10, background: C.warningSoft, borderColor: withAlpha(C.warning, 0.35) } },
        e("div", { style: { display: "flex", alignItems: "flex-start", gap: 8 } },
          e(Icon, { name: "alert", size: 14, color: C.warning }),
          e("span", { style: { color: C.warning } }, switching ? "Your switch request is pending review." : "Your request is pending review — we'll match you with a trainer soon.")
        ),
        e("div", { style: styles.stepperDotsRow },
          e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } }),
          e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } }),
          e("span", { style: styles.stepperDotSmall })
        ),
        e("p", { style: { ...styles.stepperHintLine, color: C.warning } }, "Request sent — under review"),
        e("button", {
          style: { ...styles.demoLinkBtn, marginTop: 0, padding: "0 10px", alignSelf: "flex-start", ...(cancelling ? styles.btnDisabled : {}) },
          disabled: cancelling,
          onClick: handleCancelRequest
        }, cancelling ? "Cancelling…" : "Cancel request")
      ),
      myRequest && myRequest.status === "assigned" && e("div", { style: { ...styles.setupNotice, marginBottom: 14, flexDirection: "column", alignItems: "stretch", gap: 8 } },
        e("div", { style: { display: "flex", alignItems: "flex-start", gap: 8 } },
          e(Icon, { name: "check", size: 14, color: C.ink3 }),
          e("span", null, "You've been matched with a trainer — reopen the app to see them.")
        ),
        e("div", { style: styles.stepperDotsRow },
          e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } }),
          e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } }),
          e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } })
        ),
        e("p", { style: styles.stepperHintLine }, "Matched")
      ),
      error && e("div", { style: { ...styles.errorBanner, marginBottom: 10 } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
      // Only offered to clients who currently have a real trainer — someone
      // already in the Self-Training bucket is already here, so this would
      // be a no-op for them.
      // Sept 13 2026, Jimmy: "i dont want the phrase stop training with a
      // trainer... change the design of the cluttered words and make it
      // more pro and easy on the eyes" — same option, same outcome, just
      // reworded off that phrase and restyled to match the trainer cards
      // right below it (icon circle, short primary line, the trial/payment
      // nuance dropped to smaller muted fine print instead of one long
      // run-on sentence) rather than the old plain stat-card look.
      switching && e("div", { style: { ...styles.trainerProfileCard, marginBottom: 14, display: "flex", flexDirection: "column", gap: 10 } },
        e("div", { style: { display: "flex", alignItems: "center", gap: 10 } },
          e("div", { style: { width: 40, height: 40, borderRadius: "50%", background: C.subtleFill, border: `1px solid ${C.cardBorderStrong}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 } },
            e(Icon, { name: "sparkle", size: 16, color: C.ink2 })
          ),
          e("div", { style: { display: "flex", flexDirection: "column", gap: 2, flex: 1, minWidth: 0 } },
            e("span", { style: { ...styles.exerciseName, fontSize: 15.5 } }, "Train on my own"),
            e("span", { style: { fontFamily: "'Inter', sans-serif", fontSize: 12, color: C.ink2 } }, "Manage your own workouts and diet — fully self-guided, no trainer.")
          )
        ),
        e("p", { style: { margin: 0, fontSize: 11, color: C.ink3, lineHeight: 1.5 } }, "You'll keep app access if you're already paid through — otherwise your free trial starts once this is approved."),
        e("button", {
          // Sept 19 2026 inspection fix: was only disabled by its OWN
          // requestingSelf flag — a client could tap this, then immediately
          // tap a trainer card below (or vice versa) before the first
          // insert resolved, firing two requests. anyRequestInFlight below
          // is the shared lock every request button now checks.
          style: { ...styles.saveBtn, marginTop: 2, padding: "11px", fontSize: 12.5, boxShadow: "none", ...((anyRequestInFlight || pending) ? styles.btnDisabled : {}) },
          disabled: anyRequestInFlight || pending,
          onClick: handleRequestSelfTrain
        }, pending ? "Request pending" : requestingSelf ? "Sending…" : "Request to go self-train")
      ),
      visibleTrainers.length === 0 && e("div", { style: styles.empty }, e(PeopleEmptyArt, {}), e("p", { style: styles.emptyText }, switching ? "No other trainers to show right now — check back soon." : "No trainer profiles are set up yet — check back soon.")),
      // Sept 13 2026 restyle (see expandedIds above): each card opens on a
      // single compact row — photo, name, years, a handful of specialty
      // chips to scan at a glance — with certifications and the bio moved
      // behind "View profile" instead of all landing on screen together.
      // Chips also switched from the old blue/green two-tone set to one
      // quiet neutral tone throughout, closer to how a real coaching
      // marketplace profile reads than a wall of colored tags.
      e("div", { style: { display: "flex", flexDirection: "column", gap: 12 } }, visibleTrainers.map((t, cardIndex) => {
        const specialtyChips = (t.specialties || "").split(",").map((s) => s.trim()).filter(Boolean);
        const certChips = (t.certifications || "").split(",").map((s) => s.trim()).filter(Boolean);
        const isExpanded = !!expandedIds[t.id];
        const shownSpecialties = specialtyChips.slice(0, 3);
        // Sept 13 2026, Jimmy: "the 1 more and 3 more is not showing the
        // rest!" — restSpecialties is what "+N more" was promising but the
        // expanded panel never actually rendered; it's shown there now
        // (see isExpanded block below), and hasMoreDetail now also counts
        // toward opening the card, so a trainer with extra specialties but
        // no certs/bio still gets an expand affordance.
        const restSpecialties = specialtyChips.slice(shownSpecialties.length);
        const moreSpecialtyCount = restSpecialties.length;
        const hasMoreDetail = certChips.length > 0 || !!t.bio || moreSpecialtyCount > 0;
        const disabled = anyRequestInFlight || pending;
        return e("div", {
          key: t.id, className: "trainerPickCard",
          style: { ...styles.trainerProfileCard, animation: `riseIn 0.3s ease-out ${Math.min(cardIndex, 6) * 0.05}s both` }
        },
          e("div", {
            style: { display: "flex", alignItems: "center", gap: 12, cursor: hasMoreDetail ? "pointer" : "default" },
            onClick: hasMoreDetail ? () => toggleExpanded(t.id) : undefined
          },
            // Sept 13 2026, Jimmy: "easy and pro and fun to select a
            // trainer" — a soft brand-tinted ring around the photo, purely
            // decorative, so the header row has one warm accent instead of
            // reading as flat gray-on-gray.
            e("div", { style: { padding: 2, borderRadius: "50%", border: `2px solid ${withAlpha(C.brand, 0.28)}`, flexShrink: 0, display: "flex" } },
              e(TrainerAvatar, { name: t.name, photoUrl: t.photo_url, size: 40 })
            ),
            e("div", { style: { display: "flex", flexDirection: "column", gap: 2, flex: 1, minWidth: 0 } },
              e("span", { style: { ...styles.exerciseName, fontSize: 15.5 } }, t.name || "Unnamed trainer"),
              t.years_experience != null && e("span", { style: { fontFamily: "'Inter', sans-serif", fontSize: 11.5, color: C.ink3 } }, `${t.years_experience} ${t.years_experience === 1 ? "year" : "years"} coaching`)
            ),
            hasMoreDetail && e(Icon, { name: "chevron", size: 13, color: C.ink3, style: { flexShrink: 0, transform: isExpanded ? "rotate(90deg)" : "none", transition: "transform 0.15s ease" } })
          ),
          shownSpecialties.length > 0 && e("div", { style: { display: "flex", flexWrap: "wrap", gap: 6, marginTop: 10 } },
            shownSpecialties.map((s, i) => e("span", { key: i, style: i === 0 ? styles.trainerChipPrimary : styles.trainerChipNeutral }, s)),
            // Sept 13 2026: now actually opens the card to reveal the rest
            // (used to be inert text), and underlined so it reads as tappable.
            moreSpecialtyCount > 0 && e("span", {
              onClick: (ev) => { ev.stopPropagation(); toggleExpanded(t.id); },
              style: { ...styles.trainerChipNeutral, color: C.ink3, background: "transparent", border: "none", padding: "3px 2px", cursor: "pointer", textDecoration: "underline" }
            }, `+${moreSpecialtyCount} more`)
          ),
          // Sept 13 2026, Jimmy: "the certification and about i wanted to
          // be more fun and to look clearer on each one, like we can add a
          // color or emoji related to them" — certifications are now their
          // own colored badge chips (🏅, green tint) instead of one plain
          // comma-joined sentence, and About gets a 💬 label plus a soft
          // accent callout instead of a bare paragraph. Only shown once
          // expanded, so this doesn't bring back the clutter from before.
          isExpanded && e("div", { style: { marginTop: 12, paddingTop: 12, borderTop: `1px solid ${C.cardBorder}`, display: "flex", flexDirection: "column", gap: 12 } },
            restSpecialties.length > 0 && e("div", null,
              e("span", { style: styles.trainerSectionLabel }, "More specialties"),
              e("div", { style: { display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 } },
                restSpecialties.map((s, i) => e("span", { key: i, style: styles.trainerChipNeutral }, s))
              )
            ),
            certChips.length > 0 && e("div", null,
              e("span", { style: styles.trainerSectionLabel }, "🏅 Certifications"),
              e("div", { style: { display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 } },
                certChips.map((c, i) => e("span", { key: i, style: styles.trainerChipCert }, c))
              )
            ),
            t.bio && e("div", null,
              e("span", { style: styles.trainerSectionLabel }, "💬 About"),
              e("div", { style: styles.trainerBioCallout },
                e("p", { style: { margin: 0, fontSize: 12.5, color: C.ink2, lineHeight: 1.55 } }, t.bio)
              )
            )
          ),
          hasMoreDetail && e("button", {
            type: "button", onClick: (ev) => { ev.stopPropagation(); toggleExpanded(t.id); },
            style: { display: "block", marginTop: 10, background: "none", border: "none", padding: 0, fontFamily: "'Inter', sans-serif", fontSize: 11.5, fontWeight: 600, color: C.brand, cursor: "pointer" }
          }, isExpanded ? "Hide profile" : "View full profile"),
          e("button", {
            style: { ...styles.saveBtn, marginTop: 12, padding: "11px", fontSize: 12.5, boxShadow: "none", ...(disabled ? styles.btnDisabled : {}) },
            disabled,
            onClick: (ev) => { ev.stopPropagation(); handleRequest(t.id); }
          },
            // Sept 13 2026, "fun to select a trainer" — a small icon on the
            // CTA (clock while pending, a checkmark otherwise) so the
            // button reads as a lively confirm action, not just a text pill.
            e(Icon, { name: pending ? "clock" : "check", size: 13, color: "currentColor" }),
            pending ? "Request pending" : requesting === t.id ? "Sending…" : switching ? "Request switch" : "Request this trainer"
          )
        );
      }))
    );
  }

  // Shown to a self-train client in place of the Log/Diet tabs once their
  // 14-day trial (or a previous month's payment) has run out. A client
  // still never has a "mark as paid" button of their own — only a manager
  // can flip that switch (see AppAccessCard below), after confirming the
  // Whish payment actually arrived — but PaymentStatusStepper above now
  // gives them a real "I've sent it" step instead of just instructions.
  function SelfTrainAccessLockedScreen({ profile, userEmail }) {
    const trialEnded = profile && profile.trial_ends_at && new Date(profile.trial_ends_at) <= new Date();
    return e("div", { style: { padding: "16px 18px 0" } },
      e("div", { style: { ...styles.setupNotice, flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 16 } },
        e("div", { style: { display: "flex", alignItems: "center", gap: 8 } },
          e(Icon, { name: "lock", size: 16, color: C.ink3 }),
          e("span", { style: { fontFamily: "'Oswald', sans-serif", fontWeight: 600, fontSize: 15, letterSpacing: "0.02em", color: C.ink } },
            trialEnded ? "Your free trial has ended" : "Payment due to keep using the app"
          )
        ),
        e("p", { style: { margin: 0 } }, `$${SELF_TRAIN_MONTHLY_PRICE}/month keeps this unlocked — logging workouts, tracking food, and seeing calories burned vs. eaten.`),
        e("div", { style: { display: "flex", flexDirection: "column", gap: 3, margin: "4px 0" } },
          e("p", { style: { margin: 0, fontSize: 12.5, color: C.ink2 } }, "Instead of separate apps for lifting and food tracking, it's all in one place — plus a weekly muscle-balance view and AI Chat for when there's no coach to ask."),
        ),
        e(PaymentStatusStepper, { email: userEmail, context: "self_train_access", amount: SELF_TRAIN_MONTHLY_PRICE, approvedCopy: "Approved — unlocked" })
      )
    );
  }

  // Manager-side control for a self-train client's monthly app access — same
  // manual "mark as paid" pattern as the program paywall and diet-plan
  // unlock below, just tracking a "paid through" date instead of a one-time
  // unlock, since this is the app's first recurring (not one-time) paid
  // feature. Only ever shown for a client with no real trainer — see
  // clientIsSelfTrain at the call site.
  function AppAccessCard({ clientProfile, onUpdate, onIncrementTotalDue = null }) {
    const [unlocking, setUnlocking] = useState(false);
    const [amount, setAmount] = useState(String(SELF_TRAIN_MONTHLY_PRICE));
    const [paidThrough, setPaidThrough] = useState(() => {
      const d = new Date();
      d.setDate(d.getDate() + 30);
      return d.toISOString().slice(0, 10);
    });
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    // Sept 15 2026, Jimmy: "i did turn off the access but still can see the
    // program" — this card only ever had "Mark as paid," no way to actually
    // lock a client out. Setting a past "paid through" date alone doesn't
    // do it either: hasSelfTrainAppAccess() treats an active free trial as
    // access on its own, so a client still inside their 14-day trial stays
    // fully unlocked (Log, Diet, and any already-picked program) no matter
    // what the paid-through date says. "Revoke access" below is the real
    // off switch — it clears BOTH trial_ends_at and access_paid_through, so
    // there's nothing left for hasSelfTrainAppAccess to find.
    const [revoking, setRevoking] = useState(false);
    const [confirmingRevoke, setConfirmingRevoke] = useState(false);

    if (!clientProfile) return null;

    async function handleMarkPaid() {
      setError("");
      const amt = Number(amount);
      if (!amount || isNaN(amt) || amt <= 0) { setError("Enter a valid amount."); return; }
      if (!paidThrough) { setError("Pick a paid-through date."); return; }
      if (!sb) { setError("Backend not configured yet."); return; }
      setSaving(true);
      const { data: updated, error: err } = await sb.from("client_profiles").update({ access_paid_through: paidThrough }).eq("id", clientProfile.id).select();
      if (err) { setSaving(false); setError("Couldn't save: " + err.message); return; }
      if (!updated || updated.length === 0) { setSaving(false); setError("Save was blocked by a permissions rule (0 rows updated)."); return; }
      await sb.from("client_payments").insert([{ user_id: clientProfile.user_id, client_name: clientProfile.client_name, amount: amt, paid_on: todayISO(), note: `App access — paid through ${paidThrough}` }]);
      // Sept 19 2026 inspection fix: same bug class the diet-plan/program
      // unlock fixes closed — this logged the payment but never bumped
      // total_due, so marking an app-access renewal paid made the
      // client's shown balance drift into "credit" every time even
      // though nothing was actually overpaid.
      if (onIncrementTotalDue) onIncrementTotalDue(clientProfile.id, amt);
      // Sept 12 2026, Jimmy: design audit — the locked screen used to tell a
      // client "wait for JimFit to confirm" with no way to actually see
      // that happen. Same notifyClient() pattern already used for diet/
      // program readiness, so the promise on that screen ("you'll see a
      // notice in the app") is now true instead of just reassuring copy.
      notifyClient(clientProfile.user_id, "Your access is active — you're all set!");
      setSaving(false);
      setUnlocking(false);
      if (onUpdate) onUpdate({ access_paid_through: paidThrough });
    }

    async function handleRevoke() {
      setError("");
      if (!sb) { setError("Backend not configured yet."); return; }
      setRevoking(true);
      const { data: updated, error: err } = await sb.from("client_profiles").update({ access_paid_through: null, trial_ends_at: null }).eq("id", clientProfile.id).select();
      setRevoking(false);
      setConfirmingRevoke(false);
      if (err) { setError("Couldn't save: " + err.message); return; }
      if (!updated || updated.length === 0) { setError("Save was blocked by a permissions rule (0 rows updated)."); return; }
      if (onUpdate) onUpdate({ access_paid_through: null, trial_ends_at: null });
    }

    const now = new Date();
    const trialActive = clientProfile.trial_ends_at && new Date(clientProfile.trial_ends_at) > now;
    const paidActive = clientProfile.access_paid_through && new Date(clientProfile.access_paid_through + "T23:59:59") > now;
    const statusText = paidActive
      ? `Active — paid through ${fmtDateMed(clientProfile.access_paid_through)}`
      : trialActive
      ? `Free trial — ends ${fmtDateMed(clientProfile.trial_ends_at.slice(0, 10))}`
      : clientProfile.access_paid_through
      ? `Locked — access lapsed ${fmtDateMed(clientProfile.access_paid_through)}`
      : clientProfile.trial_ends_at
      ? `Locked — trial ended ${fmtDateMed(clientProfile.trial_ends_at.slice(0, 10))}`
      : "Locked — no trial or payment on file";

    return e("div", { style: { ...styles.sessionForm, marginTop: 20 } },
      e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
        e("span", { style: styles.profileLabel }, "App access (Log + Diet + Programs)"),
        e("span", {
          style: { fontSize: 11, fontWeight: 600, letterSpacing: "0.03em", color: paidActive || trialActive ? C.good : C.ink3, display: "flex", alignItems: "center", gap: 4 }
        }, e(Icon, { name: "lock", size: 11, color: paidActive || trialActive ? C.good : C.ink3 }), statusText)
      ),
      error && e("span", { style: { ...styles.inlineError, display: "block", marginTop: 6 } }, error),
      unlocking
        ? e("div", { style: { marginTop: 10 } },
            e("label", { style: { ...styles.formLabel, marginTop: 0 } }, "Amount received"),
            e("input", { style: styles.input, type: "number", placeholder: "Amount", value: amount, onChange: (ev) => setAmount(ev.target.value) }),
            e("label", { style: styles.formLabel }, "Paid through"),
            e("input", { style: styles.input, type: "date", value: paidThrough, onChange: (ev) => setPaidThrough(ev.target.value) }),
            e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
              e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: handleMarkPaid }, saving ? "Saving…" : "Mark as paid"),
              e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setUnlocking(false); setError(""); } }, "Cancel")
            )
          )
        : confirmingRevoke
        ? e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8, marginTop: 10 } },
            e("span", { style: styles.deleteConfirmText }, "Lock this client out of Log, Diet, and any picked program right now — even if their free trial hasn't ended yet?"),
            e("div", { style: { display: "flex", gap: 8 } },
              e("button", { style: { ...styles.confirmCancelBtn, flex: 1 }, onClick: () => setConfirmingRevoke(false), disabled: revoking }, "Cancel"),
              e("button", { style: { ...styles.confirmDangerBtn, flex: 1, ...(revoking ? styles.btnDisabled : {}) }, disabled: revoking, onClick: handleRevoke }, revoking ? "…" : "Revoke access")
            )
          )
        : e("div", { style: { display: "flex", gap: 14, marginTop: 10, flexWrap: "wrap" } },
            e("button", { style: styles.demoLinkBtn, onClick: () => setUnlocking(true) }, "Mark as paid →"),
            (trialActive || paidActive) && e("button", { style: { ...styles.demoLinkBtn, color: C.critical }, onClick: () => setConfirmingRevoke(true) }, "Revoke access →")
          )
    );
  }

export { TrainerAvatar, TrainerPhotoUploader, AutoSaveTextarea, InfoSectionCard, TrainerNotOnRosterScreen, TrainerPendingApprovalScreen, TrainerPaymentOverdueScreen, TrainerFirstPaymentDueScreen, TrainerRequestsPanel, TrainersBillingPanel, TrainerMyProfilePanel, FindTrainerPanel, SelfTrainAccessLockedScreen, AppAccessCard };
